import sys
from collections import defaultdict

def longest_substring_with_k_unique(s, k):
    if not s or k <= 0:
        return -1

    n = len(s)
    if k > n:
        return -1

    # Check if k is greater than the number of unique characters in the string
    unique_in_string = len(set(s))
    if k > unique_in_string:
        return -1

    max_len = 0
    left = 0
    char_count = defaultdict(int)
    unique_chars = 0

    for right in range(n):
        if char_count[s[right]] == 0:
            unique_chars += 1
        char_count[s[right]] += 1

        while unique_chars > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                unique_chars -= 1
            left += 1

        if unique_chars == k:
            max_len = max(max_len, right - left + 1)

    if max_len == 0:
        return -1
    return max_len

def main():
    s = sys.stdin.readline().strip()
    if not s:
        print(-1)
        return
    try:
        k = int(sys.stdin.readline().strip())
    except:
        print(-1)
        return

    result = longest_substring_with_k_unique(s, k)
    print(result)

if __name__ == "__main__":
    main()
